/* Example: capital table (Improved capitalyears.c)
    The growth of capital over years
    Author: Peter Brusilovsky
 */

#include <stdio.h>

void main() {
    int year = 1, how_many_years; /* years the capital stays in bank */
    float interest_rate; /* interest rate in percents */
    float capital; /* capital in dollars */
    float annual_interest; /* annual interest in dollars */

    /* reading data */
    printf("Startup capital ($$$.cc): "); scanf("%f",&capital);
    printf("Interest rate (%% xx.xx): "); scanf("%f",&interest_rate);
    do { /* foolproof input */
        printf("How many years (positive integer): ");
        scanf("%d", &how_many_years);
    } while ( how_many_years <= 0);

    /* printing table */
    do {
        annual_interest = capital * interest_rate / 100;
        capital = capital + annual_interest;
        printf("Year %2d, capital %.2f\n", year, capital);
        year++;
    } while (year <= how_many_years);

    /* printing final results */
    printf("New capital %9.2f\n", capital);
}
